import java.lang.ref.WeakReference;
import java.util.ArrayList;
import java.util.List;

public class JvmMemoryLecture {
    record StudentSession(String name, int score) {
        @Override
        public String toString() { return name + ":" + score; }
    }

    // A static field is a GC root: whatever it references stays reachable
    static final List<byte[]> CACHE = new ArrayList<>();

    // baseScore, multiplier and scaled live in this call's stack frame and vanish on return
    static int computeScaledScore(int baseScore, int multiplier) {
        int scaled = baseScore * multiplier;
        return Math.min(scaled, 100);
    }

    // The list and the sessions are heap objects: they outlive this frame because we return a reference
    static List<StudentSession> buildSessions() {
        List<StudentSession> sessions = new ArrayList<>();
        sessions.add(new StudentSession("student-1", computeScaledScore(30, 2)));
        sessions.add(new StudentSession("student-2", computeScaledScore(35, 2)));
        sessions.add(new StudentSession("student-3", computeScaledScore(42, 3)));
        return sessions;
    }

    public static void main(String[] args) {
        List<StudentSession> sessions = buildSessions();
        System.out.println("Sessions on heap: " + sessions);
        int total = 0;
        for (StudentSession session : sessions) total += session.score();
        System.out.println("Average score: " + total / sessions.size());

        StudentSession first = sessions.get(0);
        WeakReference<StudentSession> weak = new WeakReference<>(first);
        // Deterministic only while a strong reference exists; once it is gone, GC may clear it at any time
        System.out.println("weak reference while strongly held -> same object: " + (weak.get() == first));

        for (int i = 0; i < 3; i++) CACHE.add(new byte[256 * 1024]);
        System.out.println("static cache retains " + CACHE.size() + " chunks = " + CACHE.size() * 256 + " KB (reachable from a GC root)");
        CACHE.clear(); // the arrays are now unreachable, so the GC is free to reclaim them
        System.out.println("after clear(): " + CACHE.size() + " chunks retained");
    }
}

