#include <algorithm>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

struct StudentSession {
    std::string name;
    int score;
};

// A global is a root: whatever it owns stays alive until the program ends or it is cleared
std::vector<std::vector<char>> cache;

// baseScore, multiplier and scaled live in this call's stack frame and vanish on return
int computeScaledScore(int baseScore, int multiplier) {
    int scaled = baseScore * multiplier;
    return std::min(scaled, 100);
}

// make_shared puts each session on the heap, so it outlives this frame
std::vector<std::shared_ptr<StudentSession>> buildSessions() {
    std::vector<std::shared_ptr<StudentSession>> sessions;
    sessions.push_back(std::make_shared<StudentSession>(StudentSession{"student-1", computeScaledScore(30, 2)}));
    sessions.push_back(std::make_shared<StudentSession>(StudentSession{"student-2", computeScaledScore(35, 2)}));
    sessions.push_back(std::make_shared<StudentSession>(StudentSession{"student-3", computeScaledScore(42, 3)}));
    return sessions;
}

int main() {
    auto sessions = buildSessions();
    int total = 0;
    std::cout << "Sessions on heap: [";
    for (std::size_t i = 0; i < sessions.size(); ++i) {
        std::cout << (i ? ", " : "") << sessions[i]->name << ":" << sessions[i]->score;
        total += sessions[i]->score;
    }
    std::cout << "]\n";
    std::cout << "Average score: " << total / static_cast<int>(sessions.size()) << "\n";

    std::shared_ptr<StudentSession> first = sessions[0];
    std::weak_ptr<StudentSession> weak = first; // does not keep the object alive
    std::cout << std::boolalpha << "weak reference while strongly held -> same object: " << (weak.lock() == first) << "\n";

    for (int i = 0; i < 3; ++i) cache.emplace_back(256 * 1024);
    std::cout << "static cache retains " << cache.size() << " chunks = " << cache.size() * 256 << " KB (reachable from a GC root)\n";
    cache.clear(); // in C++ the memory is freed right here; in Java it becomes eligible for GC
    std::cout << "after clear(): " << cache.size() << " chunks retained\n";
}

