import java.util.ArrayDeque;
import java.util.Deque;

public class StackHeapTrace {
    static class Counter {
        int value;
        Counter(int value) { this.value = value; }
    }

    // A model of the call stack: pushed and popped exactly when the real frames are
    static final Deque<String> frames = new ArrayDeque<>();
    static int peakDepth = 0;

    static void enter(String frame) {
        frames.addLast(frame);
        peakDepth = Math.max(peakDepth, frames.size());
    }

    static void leave() { frames.removeLast(); }

    static Counter makeCounter(int start) {
        enter("makeCounter");
        System.out.println("call stack: " + frames + " (start=" + start + " lives in this frame)");
        Counter counter = new Counter(start); // object on the heap; `counter` is only a reference
        leave();
        return counter;
    }

    static int sumTo(int n) {
        enter("sumTo(" + n + ")");
        if (n == 0) System.out.println("deepest point: " + frames);
        int result = n == 0 ? 0 : n + sumTo(n - 1);
        leave();
        return result;
    }

    public static void main(String[] args) {
        enter("main");
        System.out.println("call stack: " + frames);
        Counter a = makeCounter(10);
        System.out.println("call stack: " + frames + " (makeCounter's frame is gone, its Counter is not)");

        Counter b = a; // copies the reference, not the object
        b.value += 5;
        System.out.println("b = a copies a reference: a.value = " + a.value + ", same object: " + (a == b));

        int x = 10;
        int y = x; // copies the value itself
        y += 5;
        System.out.println("y = x copies a value: x = " + x + ", y = " + y);

        int total = sumTo(4);
        System.out.println("sumTo(4) = " + total + ", peak stack depth = " + peakDepth + " frames (main + 5 calls)");
    }
}

