public class ObjectLifecycleDemo {
    static class Resource implements AutoCloseable {
        final String name;
        String state;

        Resource(String name) {
            this.name = name; // fields were already zeroed/null before the constructor body ran
            this.state = "open";
            System.out.println("  create " + name + " (constructor ran)");
        }

        void use(boolean fail) {
            System.out.println("  use " + name);
            if (fail) throw new IllegalStateException(name + " failed");
        }

        @Override
        public void close() {
            state = "closed";
            System.out.println("  close " + name);
        }
    }

    public static void main(String[] args) {
        System.out.println("block 1: normal exit");
        Resource kept;
        try (Resource log = new Resource("log"); Resource db = new Resource("db")) {
            log.use(false);
            db.use(false);
            kept = db;
        } // closed here in reverse order of opening: db, then log

        System.out.println("block 2: exception inside the block");
        try (Resource file = new Resource("file")) {
            file.use(true);
        } catch (IllegalStateException e) {
            System.out.println("  caught after close: " + e.getMessage());
        }

        System.out.println("db is still reachable through kept, state = " + kept.state);
        kept = null; // last strong reference gone: db is now eligible for garbage collection
        System.out.println("kept = null -> db unreachable; the GC may reclaim it at any later time");
    }
}

