#include <iostream>
#include <memory>
#include <stdexcept>
#include <string>

class Resource {
public:
    explicit Resource(std::string name) : name(std::move(name)) {
        std::cout << "  create " << this->name << " (constructor ran)\n";
    }

    void use(bool fail) {
        std::cout << "  use " << name << "\n";
        if (fail) throw std::runtime_error(name + " failed");
    }

    void close() {
        state = "closed";
        std::cout << "  close " << name << "\n";
    }

    std::string name;
    std::string state = "open";
};

// Mimics try-with-resources with RAII: the destructor closes the resource when the scope ends,
// including while an exception is unwinding the stack
struct CloseOnExit {
    std::shared_ptr<Resource> resource;
    ~CloseOnExit() { resource->close(); }
};

int main() {
    std::cout << "block 1: normal exit\n";
    std::shared_ptr<Resource> kept;
    {
        auto log = std::make_shared<Resource>("log");
        CloseOnExit closeLog{log};
        auto db = std::make_shared<Resource>("db");
        CloseOnExit closeDb{db};
        log->use(false);
        db->use(false);
        kept = db;
    } // guards are destroyed in reverse order of declaration: db, then log

    std::cout << "block 2: exception inside the block\n";
    try {
        auto file = std::make_shared<Resource>("file");
        CloseOnExit closeFile{file};
        file->use(true);
    } catch (const std::runtime_error& e) {
        std::cout << "  caught after close: " << e.what() << "\n";
    }

    std::cout << "db is still reachable through kept, state = " << kept->state << "\n";
    kept.reset(); // C++ frees the object right here; a Java object would merely become eligible for GC
    std::cout << "kept = null -> db unreachable; the GC may reclaim it at any later time\n";
}

