import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

public class MarkSweepModel {
    static final Map<String, List<String>> heap = new TreeMap<>(); // object -> objects it references
    static final List<String> roots = new ArrayList<>();

    static void mark(String obj, Set<String> marked, List<String> order) {
        if (!marked.add(obj)) return; // already marked: this is what stops cycles from looping
        order.add(obj);
        for (String ref : heap.get(obj)) mark(ref, marked, order);
    }

    static void collect(int round) {
        Set<String> marked = new HashSet<>();
        List<String> order = new ArrayList<>();
        for (String root : roots) mark(root, marked, order);
        List<String> swept = new ArrayList<>();
        for (String obj : List.copyOf(heap.keySet())) {
            if (!marked.contains(obj)) {
                heap.remove(obj);
                swept.add(obj);
            }
        }
        System.out.println("GC " + round + ": roots " + roots + ", marked " + order + ", swept " + swept);
        System.out.println("heap after GC " + round + ": " + heap.keySet());
    }

    public static void main(String[] args) {
        String[][] edges = {{"A", "B"}, {"B", "C"}, {"C", "A"}, {"D", "F"}, {"F", "D"}, {"G", "B"}};
        for (String name : List.of("A", "B", "C", "D", "E", "F", "G")) heap.put(name, new ArrayList<>());
        StringBuilder refs = new StringBuilder();
        for (String[] e : edges) {
            heap.get(e[0]).add(e[1]);
            refs.append(refs.length() == 0 ? "" : " ").append(e[0]).append("->").append(e[1]);
        }
        System.out.println("heap objects: " + heap.keySet());
        System.out.println("references: " + refs);

        roots.add("A"); // a local variable in main's stack frame
        roots.add("E"); // a static field
        collect(1);

        roots.remove("A"); // main no longer needs A (e.g. the variable went out of scope)
        System.out.println("root A dropped");
        collect(2);
    }
}

