#include <algorithm>
#include <iostream>
#include <map>
#include <set>
#include <string>
#include <utility>
#include <vector>

std::map<std::string, std::vector<std::string>> heap; // object -> objects it references
std::vector<std::string> roots;

std::string show(const std::vector<std::string>& items) {
    std::string out = "[";
    for (std::size_t i = 0; i < items.size(); ++i) out += (i ? ", " : "") + items[i];
    return out + "]";
}

std::vector<std::string> heapObjects() {
    std::vector<std::string> names;
    for (const auto& [name, refs] : heap) names.push_back(name);
    return names;
}

void mark(const std::string& obj, std::set<std::string>& marked, std::vector<std::string>& order) {
    if (!marked.insert(obj).second) return; // already marked: this is what stops cycles from looping
    order.push_back(obj);
    for (const auto& ref : heap[obj]) mark(ref, marked, order);
}

void collect(int round) {
    std::set<std::string> marked;
    std::vector<std::string> order, swept;
    for (const auto& root : roots) mark(root, marked, order);
    for (const auto& name : heapObjects()) {
        if (!marked.count(name)) {
            heap.erase(name);
            swept.push_back(name);
        }
    }
    std::cout << "GC " << round << ": roots " << show(roots) << ", marked " << show(order) << ", swept " << show(swept) << "\n";
    std::cout << "heap after GC " << round << ": " << show(heapObjects()) << "\n";
}

int main() {
    std::vector<std::pair<std::string, std::string>> edges = {{"A", "B"}, {"B", "C"}, {"C", "A"}, {"D", "F"}, {"F", "D"}, {"G", "B"}};
    for (std::string name : {"A", "B", "C", "D", "E", "F", "G"}) heap[name] = {};
    std::string refs;
    for (const auto& [from, to] : edges) {
        heap[from].push_back(to);
        refs += (refs.empty() ? "" : " ") + from + "->" + to;
    }
    std::cout << "heap objects: " << show(heapObjects()) << "\n";
    std::cout << "references: " << refs << "\n";

    roots = {"A", "E"}; // A: a local variable in main's frame, E: a static field
    collect(1);

    roots.erase(std::find(roots.begin(), roots.end(), "A")); // main no longer needs A
    std::cout << "root A dropped\n";
    collect(2);
}

