import java.lang.ref.WeakReference;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class ReferenceStrengthModel {
    // Model of a reference: kind is "strong", "soft" or "weak"; target becomes null when cleared
    static class Ref {
        final String kind;
        String target;

        Ref(String kind, String target) {
            this.kind = kind;
            this.target = target;
        }

        String get() { return target; }
    }

    // One GC cycle: weak refs to objects without a strong ref are cleared; soft ones only under pressure
    static void gc(List<Ref> refs, boolean lowMemory) {
        Set<String> stronglyHeld = new HashSet<>();
        for (Ref r : refs) if (r.kind.equals("strong")) stronglyHeld.add(r.target);
        for (Ref r : refs) {
            if (r.target == null || stronglyHeld.contains(r.target)) continue;
            if (r.kind.equals("weak") || (r.kind.equals("soft") && lowMemory)) r.target = null;
        }
    }

    static String show(List<Ref> refs) {
        List<String> parts = new ArrayList<>();
        for (Ref r : refs) parts.add(r.kind + "->" + r.get());
        return String.join(" ", parts);
    }

    public static void main(String[] args) {
        List<Ref> refs = List.of(
            new Ref("strong", "report"), new Ref("soft", "thumbnail"),
            new Ref("weak", "session"), new Ref("weak", "config"), new Ref("strong", "config"));
        System.out.println("before any GC:       " + show(refs));
        gc(refs, false);
        System.out.println("GC, memory is fine:  " + show(refs));
        gc(refs, true);
        System.out.println("GC, memory is low:   " + show(refs));

        // The real API: the only deterministic case is while a strong reference still exists
        StringBuilder profile = new StringBuilder("profile");
        WeakReference<StringBuilder> weak = new WeakReference<>(profile);
        System.out.println("real weak reference while strongly held -> same object: " + (weak.get() == profile));
    }
}

