#include <iostream>
#include <memory>
#include <set>
#include <string>
#include <vector>

// Model of a reference: kind is "strong", "soft" or "weak"; target becomes "null" when cleared
struct Ref {
    std::string kind;
    std::string target;
};

// One GC cycle: weak refs to objects without a strong ref are cleared; soft ones only under pressure
void gc(std::vector<Ref>& refs, bool lowMemory) {
    std::set<std::string> stronglyHeld;
    for (const auto& r : refs) if (r.kind == "strong") stronglyHeld.insert(r.target);
    for (auto& r : refs) {
        if (r.target == "null" || stronglyHeld.count(r.target)) continue;
        if (r.kind == "weak" || (r.kind == "soft" && lowMemory)) r.target = "null";
    }
}

std::string show(const std::vector<Ref>& refs) {
    std::string out;
    for (const auto& r : refs) out += (out.empty() ? "" : " ") + r.kind + "->" + r.target;
    return out;
}

int main() {
    std::vector<Ref> refs = {{"strong", "report"}, {"soft", "thumbnail"}, {"weak", "session"},
                             {"weak", "config"}, {"strong", "config"}};
    std::cout << "before any GC:       " << show(refs) << "\n";
    gc(refs, false);
    std::cout << "GC, memory is fine:  " << show(refs) << "\n";
