import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class ListenerLeakDemo {
    interface Listener { void onEvent(String event); }

    static class EventBus {
        private final List<Listener> listeners = new ArrayList<>();
        void register(Listener l) { listeners.add(l); }
        void unregister(Listener l) { listeners.remove(l); }
        int size() { return listeners.size(); }
        int publish(String event) {
            for (Listener l : listeners) l.onEvent(event);
            return listeners.size();
        }
    }

    static class Screen implements Listener {
        final byte[] pixels = new byte[1024]; // retained for as long as the Screen is reachable
        public void onEvent(String event) { /* would repaint */ }
    }

    // Static buses live as long as the program, so everything they reference does too
    static final EventBus LEAKY_BUS = new EventBus();
    static final EventBus FIXED_BUS = new EventBus();

    static void openAndCloseScreens(EventBus bus, int count, boolean unregisterOnClose) {
        for (int i = 0; i < count; i++) {
            Screen screen = new Screen();
            bus.register(screen);
            // ... the screen is shown and then closed ...
            if (unregisterOnClose) bus.unregister(screen);
        }
    }

    public static void main(String[] args) {
        openAndCloseScreens(LEAKY_BUS, 5, false);
        int delivered = LEAKY_BUS.publish("theme-changed");
        System.out.println("leaky: 5 closed screens, bus holds " + LEAKY_BUS.size() + " listeners = " + LEAKY_BUS.size() * 1024 + " bytes still reachable");
        System.out.println("leaky: one event was delivered to " + delivered + " closed screens");
        openAndCloseScreens(FIXED_BUS, 5, true);
        System.out.println("fixed: 5 closed screens, bus holds " + FIXED_BUS.size() + " listeners = " + FIXED_BUS.size() * 1024 + " bytes still reachable");

        Map<String, String> unbounded = new HashMap<>();
        Map<String, String> lru = new LinkedHashMap<>(16, 0.75f, true) { // true = access order
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, String> eldest) { return size() > 3; }
        };
        for (int i = 1; i <= 8; i++) {
            unbounded.put("req-" + i, "response-" + i);
            lru.put("req-" + i, "response-" + i);
        }
        System.out.println("unbounded cache after 8 requests: " + unbounded.size() + " entries");
        System.out.println("LRU cache (max 3) after 8 requests: " + lru.keySet());
        lru.get("req-6"); // a read makes req-6 the most recently used
        lru.put("req-9", "response-9");
        System.out.println("after get(req-6) and put(req-9): " + lru.keySet());
    }
}

