// Minimal LRU cache: the list keeps keys from least to most recently used
struct LruCache {
    std::size_t capacity;
    std::list<std::string> order;
    std::map<std::string, std::string> values;

    void touch(const std::string& key) {
        order.remove(key);
        order.push_back(key);
    }
    void put(const std::string& key, const std::string& value) {
        values[key] = value;
        touch(key);
        if (order.size() > capacity) {
            values.erase(order.front()); // evict the least recently used entry
            order.pop_front();
        }
    }
    void get(const std::string& key) { if (values.count(key)) touch(key); }
    std::string keys() const {
        std::string out = "[";
        for (const auto& k : order) out += (out.size() > 1 ? ", " : "") + k;
        return out + "]";
    }
};

