class Solution {
    static String compress(String s) {
        StringBuilder sb = new StringBuilder();   // one growing buffer, no copies per step
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            int run = 0;
            while (i < s.length() && s.charAt(i) == c) {   // count this run
                run++;
                i++;
            }
            sb.append(c).append(run);
        }
        return sb.toString();
    }
}

